-- Jalankan di Supabase SQL Editor. Tidak menghapus atau mengubah tabel films.
create table if not exists public.news_sources(id bigint generated by default as identity primary key,name text not null,feed_url text not null unique,category text not null default 'Nasional',region text not null default 'Indonesia',usage_permission text not null default 'link_only' check(usage_permission in ('link_only','licensed','press_release')),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.news_items(id bigint generated by default as identity primary key,source_id bigint references public.news_sources(id) on delete set null,source_name text not null,title text not null,excerpt text default '',source_url text not null unique,image_url text,category text default 'Nasional',region text default 'Indonesia',published_at timestamptz,raw_guid text,status text not null default 'new' check(status in ('new','review','used','ignored')),created_at timestamptz not null default now());
create table if not exists public.news_articles(id bigint generated by default as identity primary key,title text not null,slug text not null unique,excerpt text default '',body text not null,category text not null default 'Daerah',region text default 'Bangil',image_url text,image_credit text,source_name text,source_url text,status text not null default 'review' check(status in ('draft','review','published','rejected','archived')),created_at timestamptz not null default now(),published_at timestamptz);
alter table public.news_sources enable row level security;alter table public.news_items enable row level security;alter table public.news_articles enable row level security;
revoke all on public.news_sources from anon,authenticated;revoke all on public.news_items from anon,authenticated;revoke all on public.news_articles from anon,authenticated;
create index if not exists news_articles_status_published_idx on public.news_articles(status,published_at desc);
create index if not exists news_items_status_idx on public.news_items(status,created_at desc);
